/*
 * A102035  Carrie's triangle, read by rows, where the terms are generated by
 *          the rule: T(n,k) = T(n-1,k) + T(n-1,k-1) + T(n-2,k-1) + T(n-3,k-1)
 *          + T(n-3,k), with T(0,0)=1.
 * https://oeis.org/A102035
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   Carrie's triangle, read by rows. T(n,k) = T(n-1,k) + T(n-1,k-1)
 *            + T(n-2,k-1) + T(n-3,k-1) + T(n-3,k), T(0,0)=1. a(n) is the
 *            element obtained by row‑major order
 * Range:     u8 n <= 37, u16 n <= 67, u32 n <= 67, u64 n <= 67, u128 n <= 67,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* global storage for the triangle */
static seq_t **triangle = NULL;
static idx_t max_row = (idx_t)-1;   /* largest row that has been built */

/* binary search for the largest r such that r(r+1)/2 <= n */
static inline idx_t row_of(idx_t n)
{
    double est = sqrt((double)(2.0 * n + 1.0));
    idx_t high = (idx_t)(est + 2.0);
    while ((idx_t)((__int128)high * (high + 1) / 2) <= n)
        high <<= 1;
    idx_t low = 0;
    while (low <= high) {
        idx_t mid = low + (high - low) / 2;
        idx_t t = (idx_t)((__int128)mid * (mid + 1) / 2);
        if (t <= n)
            low = mid + 1;
        else
            high = mid - 1;
    }
    return high;   /* r such that r(r+1)/2 <= n < (r+1)(r+2)/2 */
}

/* ensure that rows 0 .. r are computed */
static void ensure_rows_up_to(idx_t r)
{
    if (triangle == NULL) {
        triangle = (seq_t **)malloc((r + 1) * sizeof(seq_t *));
        if (triangle == NULL) abort();
    } else if (max_row < r) {
        seq_t **tmp = (seq_t **)realloc(triangle, (r + 1) * sizeof(seq_t *));
        if (tmp == NULL) abort();
        triangle = tmp;
    }
    for (idx_t i = max_row + 1; i <= r; ++i) {
        triangle[i] = (seq_t *)malloc((i + 1) * sizeof(seq_t));
        if (triangle[i] == NULL) abort();
        if (i == 0) {
            triangle[0][0] = (seq_t)1;
        } else {
            for (idx_t k = 0; k <= i; ++k) {
                seq_t val = 0;
                /* T(n-1,k) */
                if (k <= i - 1) val += triangle[i - 1][k];
                /* T(n-1,k-1) */
                if (k >= 1) val += triangle[i - 1][k - 1];
                /* T(n-2,k-1) */
                if (i >= 2 && k >= 1 && k <= i - 1)
                    val += triangle[i - 2][k - 1];
                /* T(n-3,k-1) */
                if (i >= 3 && k >= 1 && k <= i - 2)
                    val += triangle[i - 3][k - 1];
                /* T(n-3,k) */
                if (i >= 3 && k <= i - 3)
                    val += triangle[i - 3][k];
                triangle[i][k] = val;
            }
        }
    }
    max_row = r;
}

seq_t a(idx_t n)
{
    idx_t r = row_of(n);
    idx_t t = (idx_t)((__int128)r * (r + 1) / 2);
    idx_t c = n - t;
    ensure_rows_up_to(r);
    return triangle[r][c];
}
